files={f:open(f).read() for f in glob.glob('src/p*.txt')}
for old,new in R:
    done=False
    for f,s in files.items():
        i=s.find(old)
        if i<0: continue
        j=i+len(old)
        cite=''
        if s[j:j+2]=='[[':
            k=s.index(']]',j)+2; cite=s[j:k]; j=k
        newt=new.replace('@@',cite)
        if '@@' not in new: newt=new+cite
        files[f]=s[:i]+newt+s[j:]
        done=True;break
    if not done: print('MISS',old[:70])
for f,s in files.items(): open(f,'w').write(s)
